  (() => {
    const HOST = 'https://chatwoot.teotec.org';
    const raw = String($('Normalizar evento').first().json.audio_url || '');

    // Relativa: siempre contra el host de Chatwoot.
    if (!/^https?:\/\//i.test(raw)) return HOST + (raw.charAt(0) === '/' ? raw : '/' + raw);

    const m = raw.match(/^https?:\/\/([^/?#]+)([^?#]*)(\?[^#]*)?/i);
    const host = (m ? m[1] : '').toLowerCase().split(':')[0];

    // Solo Chatwoot o el dominio interno de EasyPanel; cualquier otro host
    // significaria mandarle la credencial de Chatwoot a un tercero.
    const permitido = host === 'chatwoot.teotec.org' || /(^|\.)easypanel\.host$/.test(host);
    if (!permitido) throw new Error('data_url con host no permitido: ' + host);

    return HOST + (m[2] || '') + (m[3] || '');
  })()
}}

