  const normalizar=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ').trim();
  const cliente=normalizar(textoCliente);
  if(!/[?¿]|\b(?:cuanto|cuando|donde|que|como|tienen|hay|atienden|abren|cierran|me (?:decis|confirmas|pasas|contas)|quiero saber)\b/.test(cliente))return {texto:'',faq_preservadas:[],faq_pendientes:[]};
  const temas=Object.entries({demora:/tarda|demora|plazo|cuanto.*(?:hacer|confeccion|colocar)/,garantia:/garantia/,ubicacion:/donde|direccion|ubicacion/,horario:/horario|atienden|abren|cierran/,medidas:/medidas?|compatib|le va|sirve para/,logo:/logo|puede decir|puedo poner|bordad|texto|nombre/}).filter(([,re])=>re.test(cliente)).map(([tema])=>tema);
  const productos=[...new Set((resultado.items??[]).map(i=>i.producto))];
  const uno=productos.length===1?productos[0]:null;
  const reglas=[
    ['demora','fundas',/^(?:la )?confeccion(?: aproximada)?(?: es de| tarda| demora| lleva)? (?:aproximadamente )?5 dias habiles desde (?:la )?sena$/,'La confección aproximada es de 5 días hábiles desde la seña.'],
    ['demora','tipo tapizado',/^(?:la )?confeccion(?: aproximada)?(?: es de| tarda| demora| lleva)? (?:aproximadamente )?7 dias habiles desde (?:la )?sena$/,'La confección aproximada es de 7 días hábiles desde la seña.'],
    ['demora','fundas',/^(?:la )?colocacion(?: es de| tarda| demora| lleva)? (?:entre )?4 (?:a|y) 5 horas$/,'La colocación lleva entre 4 y 5 horas.'],
    ['demora','tipo tapizado',/^(?:la )?colocacion(?: es de| tarda| demora| lleva)? una jornada laboral(?:, usualmente de 9 a 18)?$/,'La colocación lleva una jornada laboral, usualmente de 9 a 18.'],
    ['garantia','fundas',/^contas con garantia de fabrica por 90 dias desde su colocacion$/,'Contas con garantía de fábrica por 90 días desde su colocación'],
    ['garantia','tipo tapizado',/^contas con garantia de fabrica por 90 dias desde su colocacion$/,'Contas con garantía de fábrica por 90 días desde su colocación'],
    ['ubicacion',null,/^(?:📍)?la direccion es av[.]? olivera 1265\s*, caba$/,'📍La dirección es Av. Olivera 1265 , CABA.'],
    ['ubicacion',null,/^nuestra ubicacion exacta la podes ver ingresando a este link https:\/\/maps[.]app[.]goo[.]gl\/nsyib1thu4wcn2l8a\?g_st=ipc$/,'Nuestra ubicación exacta la podes ver ingresando a este link https://maps.app.goo.gl/Nsyib1THu4WCN2L8A?g_st=ipc'],
    ['horario',null,/^te esperamos de lunes a viernes de 9 a 18 hs y sabado de 9 a 14 hs$/,'Te esperamos de lunes a viernes de 9 a 18 hs y sábado de 9 a 14 hs'],
    ['logo',null,/^(?:el )?logo solicitado (?:necesita|requiere) confirmacion de candela$/,'El logo solicitado necesita confirmación de Candela.'],
  ];
  const frases=String(raw??'').replace(/\bAv\./g,'Av').split(/\n+|;|(?<=[.!?])\s+(?!\S*https?:)/).map(s=>normalizar(s).replace(/[.!?]+$/,''));
  const elegidas=reglas.filter(([tema,producto,re])=>temas.includes(tema)&&(!producto||producto===uno)&&frases.some(f=>re.test(f)));
  const preservadas=[...new Set(elegidas.map(r=>r[0]))];
  return {texto:[...new Set(elegidas.map(r=>r[3]))].join('\n\n'),faq_preservadas:preservadas,faq_pendientes:temas.filter(t=>!preservadas.includes(t))};
}


// Rescate acotado: sólo texto humano actual inequívoco; no clasifica preferencias comerciales.
function solicitudHumanaExplicita(texto) {
  if(typeof texto!=='string'||texto.length>20000)return null;
  const t=texto.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  if(/\bya (?:la |lo )?mande\b/.test(t)&&/\bme confirmas si llego\b/.test(t)&&!/(?:\bno\b|["“”«»])/.test(t))return 'pago';
  // Consultar un valor por medio de pago no confirma una compra ni un pago inmediato.
  const consultaPago=/\b(?:efectivo|transferencia|cuotas|debito|tarjeta|medios? de pago)\b/.test(t)
    && /\b(?:cuanto (?:sale|cuesta|vale|seria|queda|quedaria)|que (?:precio|valor)|(?:puedo|se puede) pagar|aceptan)\b|\b(?:precio|valor|importe|costo)\s*\?/.test(t)
    && !/\b(?:ahora|ya|comprar|reservar|reservame|agendame)\b/.test(t);
  for(const parte of t.split(/[\n,;.!]+/)) {
    const f=parte.replace(/\s+/g,' ').trim();
    if(!f||/\b(?:no|nunca|tampoco|si|quizas|tal vez|mas adelante|dije|dicho)\b|["“”«»]/.test(f))continue;
    if(/\b(?:pasame|dame|mandame|enviame|necesito|quiero|me pasas|me podes pasar)\s+(?:(?:el|tu|su)\s+)?(?:alias|cbu)\b/.test(f)||/\b(?:uso|puedo usar)\s+(?:el\s+)?alias\b/.test(f))return 'pago';
    if(/\b(?:ya pague|ya transferi|voy a pagar|voy a transferir)\b/.test(f)
      || /\bquiero pagar\b/.test(f)&&!consultaPago)return 'pago';
    if(/\b(?:quiero|necesito|quisiera)\s+(?:hablar|seguir|continuar)\s+con\s+(?:una?\s+)?(?:persona|humano|asesor|alguien|candela)\b/.test(f)
      ||/\b(?:me pasas|pasame|me podes pasar|lo veo|lo hablo)\s+con\s+(?:una?\s+)?(?:persona|humano|asesor|alguien|candela)\b/.test(f)
      ||/\bcon candela para (?:encargar|pagar|reservar)\b/.test(f)
      ||/\b(?:alguien me lo puede confirmar|quien me lo puede ver)\b/.test(f))return 'persona';
    if(/\b(?:quiero|necesito|quisiera)\s+(?:(?:un|sacar|reservar|coordinar|agendar)\s+)?turno\b/.test(f)||/\b(?:reservame|agendame|dame)\s+(?:un\s+)?turno\b/.test(f))return 'turno';
    if(/\b(?:quiero|necesito|quisiera)\s+reservar\b/.test(f))return 'reserva';
    if(/\b(?:quiero|necesito|tengo)\s+(?:(?:hacer|presentar)\s+)?(?:un\s+)?reclamo\b/.test(f)
      ||/\bme (?:la|lo) cambian\b/.test(f)&&/\b(?:rompio|rota|roto|reclamo)\b/.test(t))return 'posventa';
  }
  return null;
}

// Memoria interna, nunca salida al cliente: proyecta sólo una observación confirmada del executor.
function memoriaCotizacionConfirmada(resultado) {
  if (!resultado || !['cotizado','parcial'].includes(resultado.estado) || resultado.cotizacion_enviada !== true
      || !['aceptado','omitido'].includes(resultado.envio?.estado)
      || !Number.isSafeInteger(resultado.envio.chatwoot_message_id) || resultado.envio.chatwoot_message_id <= 0
      || !Array.isArray(resultado.items) || resultado.items.length < 1 || resultado.items.length > 10) return null;
  if (resultado.metodo_pago !== undefined && !['transferencia','efectivo','cuotas'].includes(resultado.metodo_pago)) return null;
  if (resultado.pregunta_comercial_incluida !== undefined && typeof resultado.pregunta_comercial_incluida !== 'boolean') return null;
  const productos = new Set(['fundas','tipo tapizado','tapiceria','alfombra','funda baul','cobertor caja','espuma','otros','cubrevolante']);
  const estados = new Set(['cotizado','requiere_aclaracion','sin_precio','no_encontrado']);
  const textoSeguro = v => v === undefined || v === null || (typeof v === 'string' && v.length <= 500
    && !/[\u0000-\u001f\u007f<>`]/.test(v) && !/https?:\/\/|www[.]/i.test(v) && !contieneImporte(v));
  if (resultado.items.some(i => !i || !productos.has(i.producto) || !estados.has(i.estado)
      || !Number.isSafeInteger(i.cantidad) || i.cantidad < 1 || i.cantidad > 10
      || !textoSeguro(i.modelo) || !textoSeguro(i.configuracion))) return null;
  const cotizados = resultado.items.filter(i => i.estado === 'cotizado').length;
  if (!cotizados || (resultado.estado === 'cotizado' && cotizados !== resultado.items.length)
      || (resultado.estado === 'parcial' && cotizados === resultado.items.length)) return null;
  const items = resultado.items.map(i => ({producto:i.producto,modelo:i.modelo??null,configuracion:i.configuracion??null,cantidad:i.cantidad,estado:i.estado}));
  return '[Registro interno de cotización confirmada] ' + JSON.stringify({herramienta:'buscar_precio',estado:resultado.estado,
    situacion:resultado.envio.estado === 'aceptado' ? 'aceptada_por_chatwoot' : 'ya_aceptada_por_chatwoot',items,
    ...(resultado.metodo_pago !== undefined ? {metodo_pago:resultado.metodo_pago} : {}),
    ...(resultado.pregunta_comercial_incluida !== undefined ? {pregunta_comercial_incluida:resultado.pregunta_comercial_incluida} : {})});
}

// El registro sirve de contexto al modelo; su marcador o estructura jamás son texto comercial.
function contieneRegistroInterno(texto) {
  const t=String(texto??'').normalize('NFD').replace(/[\u0300-\u036f\u200b-\u200d\ufeff]/g,'').toLowerCase()
    .replace(/[“”]/g,'"').replace(/[‘’]/g,"'").replace(/\\(["'])/g,'$1').replace(/\s+/g,' ');
  const etiqueta='(?:registro|resumen|nota|memoria|evento)\\s+intern[oa]';
  const tema='(?:cotizacion|presupuesto|buscar_precio)';
  return new RegExp('\\b'+etiqueta+'\\b[^.!?]{0,90}\\b'+tema+'\\b').test(t)
    || new RegExp('\\b'+tema+'\\b[^.!?]{0,90}\\b'+etiqueta+'\\b').test(t)
    || /\bpregunta[_ ]+comercial[_ ]+incluida["']?\s*[:=]/.test(t)
    || /\bsituacion["']?\s*[:=]\s*["']?(?:ya[_ ]+)?aceptada[_ ]+por[_ ]+chatwoot\b/.test(t)
    || /\bherramienta["']?\s*[:=]\s*["']?buscar_precio\b/.test(t);
}

// Pasado o participio afirman un presupuesto ya enviado; «te paso/te mando/te envío» lo anuncia, salvo una finalidad
// o condición previa en la misma frase («así te paso…», «cuando me confirmes te paso…»). «Envío» sin «te» es el sustantivo.
function anunciaCotizacionSinAccion(n) {
  return n.split(/[.!?\n]+/).some(frase => {
    for (const m of frase.matchAll(/\b(?:te\s+)?(envie|mande|pase|actualice|enviad[oa]|actualizad[oa])\b.{0,45}?(?:cotizacion|presupuesto)/g)) {
      if (/^(?:envie|mande|pase)$/.test(m[1]) && /\bpara que\s+$/.test(frase.slice(0, m.index))) continue;
      return true;
    }
    if (/(?:cotizacion|presupuesto)\b.{0,30}(?:enviad[oa]|actualizad[oa])/.test(frase)) return true;
    for (const m of frase.matchAll(/\bte\s+(?:paso|envio|mando)\b.{0,45}?(?:cotizacion|presupuesto)/g))
      if (!/\b(?:asi|para que|cuando|apenas|en cuanto|una vez que)\b|\bsi\s+[a-z]/.test(frase.slice(0, m.index))) return true;
    return false;
  });
}

function controlarSalidaComercial(agente={}, {texto_cliente=''}={}) {
  const raw=typeof agente.output==='string'?agente.output:'';
  const pasos=Array.isArray(agente.intermediateSteps)?agente.intermediateSteps:[];
  const observaciones=pasos.map(p=>({tool:p?.action?.tool,valor:observacionUnica(p?.observation)})).filter(o=>['derivar_humano','buscar_precio','enviar_multimedia'].includes(o.tool));
  const responder=(output,motivo,requiere_derivacion=false,extra={})=>({output,requiere_derivacion,bot_pausado:extra.bot_pausado===true,...(extra.estado?{estado:extra.estado}:{}),
    control_salida:{motivo,modificada:output!==raw,importe_modelo_bloqueado:contieneImporte(raw),resultado_incierto:false,faq_pendientes:[],faq_preservadas:[],...extra}});
  const pausa=observaciones.find(({valor:v})=>v?.bot_pausado===true||v?.envio?.estado==='control_humano'||['derivado','control_humano'].includes(v?.estado));
  if(pausa)return responder('','control_humano',false,{bot_pausado:true,estado:pausa.valor.estado??'control_humano'});
  const humano=observaciones.filter(o=>o.tool==='derivar_humano');
  if(humano.length){
    const r=humano.at(-1).valor;
    const valido=r&&['pendiente_asignacion','parcial','fallido','desconocido','simulado','entrada_invalida'].includes(r.estado)&&typeof r.continuacion_obligatoria==='string';
    // Ausencia de contrato se hace visible; nunca dispara otra derivación.
    return responder(valido?r.continuacion_obligatoria:'No pude confirmar el pase. Esa parte necesita revisión del equipo.','resultado_derivacion',false,{resultado_incierto:!valido||r.estado!=='simulado',estado:r?.estado??'desconocido'});
  }
  const precios=observaciones.filter(o=>o.tool==='buscar_precio');
  const ultimoPrecio=precios.at(-1)?.valor;
  if(ultimoPrecio?.estado==='metodo_no_confirmado'&&ultimoPrecio.requiere_derivacion==='revision_especial'&&ultimoPrecio.envio?.estado==='no_corresponde')
    return responder('','revision_especial',true);
  const solicitud=solicitudHumanaExplicita(texto_cliente);
  if(solicitud)return responder('','solicitud_humana_no_atendida',true,{solicitud_humana_detectada:solicitud});
  if(precios.length){
    const r=precios.at(-1).valor;
    if(r&&['cotizado','parcial','requiere_aclaracion','no_disponible','entrada_invalida','error_consulta','requiere_modalidad','metodo_no_confirmado','metodo_no_disponible'].includes(r.estado)&&['aceptado','omitido','fallido','desconocido','simulado','no_corresponde'].includes(r.envio?.estado)&&typeof r.continuacion_obligatoria==='string'){
      const {texto,...faq}=preservarFaq(raw,texto_cliente,r);
      const salida=responder([texto,r.continuacion_obligatoria].filter(Boolean).join('\n\n'),'continuacion_de_herramienta',false,{...faq,resultado_incierto:['fallido','desconocido'].includes(r.envio.estado)||r.estado==='error_consulta'});
      const memoria=memoriaCotizacionConfirmada(r);
      if(memoria)salida.memoria_output=[salida.output,memoria].filter(Boolean).join('\n\n');
      return salida;
    }
    // Una ejecución sin contrato verificable no autoriza reconstruir presupuesto ni reintentar.
    return responder('No pude confirmar el resultado de la consulta de precios. Esa parte necesita revisión del equipo.','precio_sin_contrato',false,{resultado_incierto:true});
  }
  if(contieneRegistroInterno(raw))return responder('','registro_interno_no_publicable',true);
  if(contieneImporte(raw))return responder('','importe_sin_herramienta',true);
  const n=raw.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  // Evita afirmar un presupuesto enviado/actualizado sin la acción correspondiente en este turno.
  if(anunciaCotizacionSinAccion(n))
    return responder('','cotizacion_sin_accion',true);
  return responder(raw,'texto_sin_importes');
}

const dato=$input.first().json;
if(dato.control_salida&&typeof dato.output==='string')return [{json:dato,pairedItem:{item:0}}];
const raw=$('AI Agent').first().json.output;
const resultado=controlarSalidaComercial({output:raw,intermediateSteps:[{action:{tool:'derivar_humano'},observation:dato}]},{texto_cliente:$('datos_finales1').first().json.texto});
resultado.control_salida.origen='revision_deterministica';
return [{json:resultado,pairedItem:{item:0}}];

const esComandoBorrar=function esComandoBorrar(texto){
  if(typeof texto!=='string')return false;
  const t=texto.normalize('NFKC').normalize('NFD').replace(/\p{M}/gu,'').toLowerCase()
    .replace(/^[\s\p{P}]+|[\s\p{P}]+$/gu,'').replace(/\s+/gu,' ');
  return /^(?:borrar|borra|borrame)(?: (?:(?:mi|la) memoria|el historial|todo))?$/.test(t);
};const verificarComandoPersistido=function verificarComandoPersistido(response,evento,ahoraMs){
  const invalid=motivo=>({ok:false,motivo});
  const id=v=>typeof v==='string'&&/^[1-9]\d{0,31}$/.test(v)?v:Number.isSafeInteger(v)&&v>0?String(v):null;
  const conv=id(evento?.conversation_id),message=id(evento?.message_id);
  if(evento?.account_id!==1||!conv||!message||typeof evento?.telefono!=='string'||!evento.telefono.trim()||evento?.is_audio!==false||!esComandoBorrar(evento?.body?.content))return invalid('evento_invalido');
  if(!Number.isSafeInteger(ahoraMs)||ahoraMs<=0)return invalid('reloj_no_verificable');
  const raw=response?.statusCode;
  const status=typeof raw==='number'?raw:typeof raw==='string'&&/^\d{3}$/.test(raw)?Number(raw):null;
  if(!Number.isInteger(status)||status<200||status>=300||response?.error)return invalid('mensajes_no_verificables');
  const body=response?.body;
  if(!body||typeof body!=='object'||Array.isArray(body)||!Array.isArray(body.payload)||(body.account_id!==undefined&&body.account_id!==1))return invalid('mensajes_no_verificables');
  const coincidencias=body.payload.filter(m=>m&&typeof m==='object'&&!Array.isArray(m)&&id(m.id)===message);
  if(coincidencias.length!==1)return invalid('mensaje_no_unico');
  const m=coincidencias[0];
  if(id(m.conversation_id)!==conv||(m.account_id!==undefined&&m.account_id!==1)||![0,'incoming'].includes(m.message_type)||m.private!==false)return invalid('mensaje_no_coincide');
  if(m.sender?.type!=='contact'||m.sender.phone_number!==evento.telefono)return invalid('contacto_no_coincide');
  if(m.content_type==='audio'||(Array.isArray(m.attachments)&&m.attachments.some(a=>a?.file_type==='audio')))return invalid('mensaje_persistido_audio');
  const normalizar=s=>s.normalize('NFKC').trim().replace(/\s+/gu,' ');
  if(!esComandoBorrar(m.content)||normalizar(m.content)!==normalizar(evento.body.content))return invalid('comando_no_coincide');
  if(typeof m.created_at!=='number'||!Number.isFinite(m.created_at)||m.created_at<=0)return invalid('fecha_no_verificable');
  const edadMs=ahoraMs-m.created_at*1000;
  if(!Number.isFinite(edadMs)||edadMs>600000||edadMs< -60000)return invalid('comando_fuera_de_ventana');
  return {ok:true,motivo:null};
};return [{json:verificarComandoPersistido($input.first().json,$('Normalizar evento').first().json,Date.now())}];

