  // Proteger antes de limpiar Markdown: _, *, ?, #, &, = y puntos pueden ser
  // parte del enlace. Solo se separan sus delimitadores externos de énfasis.
  text = text.replace(/(?:https?:\/\/|www\.)[^\s<>"`]+|[\w.+-]+@[\w.-]+\.[a-z]{2,}/gi, (s, offset, whole) => {
