    .replace(/^[\t ]*(?:[-+*•◦▪‣]|\d{1,9}[.)])[\t ]+(?:\[[ xX]\][\t ]+)?/gm, '')
    .replace(/<([\uE000]\d+[\uE001])>/g, '$1')
