        || /^colocar(?:lo|la|los|las)? en (?:(?:el|su|tu) )?(?:taller|caba)$/.test(simple)
        || /\b(?:prefiero|quiero|necesito)\s+colocar(?:lo|la|los|las)?\s+en\s+(?:(?:el|su|tu)\s+)?(?:taller|caba)\b/.test(f);
