const evaluarControlHumanoSalida = function evaluarControlHumanoSalida(respuesta,contexto,resultadoAgente={}) {
  if(contexto?.account_id!==1||!Number.isSafeInteger(contexto?.conversation_id)||contexto.conversation_id<=0)
    throw new Error('Contexto de salida no verificable');
  if(respuesta?.error||!Number.isInteger(respuesta?.statusCode)||respuesta.statusCode<200||respuesta.statusCode>=300)
    throw new Error('No se pudo verificar control humano antes de responder');
  const c=respuesta.body;
  if(!c||typeof c!=='object'||Array.isArray(c)||c.id!==contexto.conversation_id||
      (c.account_id!==undefined&&c.account_id!==contexto.account_id))
    throw new Error('Identidad de conversación no verificable antes de responder');
  if(!Array.isArray(c.labels))throw new Error('Etiquetas no verificables antes de responder');
  const labels=c.labels.map(l=>{
    const valor=typeof l==='string'?l:l&&typeof l==='object'&&!Array.isArray(l)?(l.title??l.name):null;
    if(typeof valor!=='string')throw new Error('Etiqueta no verificable antes de responder');
    return valor.normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase().replace(/[_ -]+/g,' ');
  });
  // Si el caller conserva un estado operativo explícito, solo puede cerrar la salida.
  // Nunca interpretamos el texto libre del LLM como una autorización ni como un estado.
  const pausado=labels.some(l=>l==='humano'||l==='control humano')||
    resultadoAgente?.bot_pausado===true||['derivado','control_humano'].includes(resultadoAgente?.estado);
  return {permitir_envio:!pausado,bot_pausado:pausado};
};
